def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row if v != 0)
    marker = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Each connected marker component is a pattern to replicate wherever all
    # its corresponding cells are background zeros.
    unseen = set(points)
    patterns = []
    while unseen:
        start = unseen.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    q.append(p)
        minr = min(r for r, c in comp)
        minc = min(c for r, c in comp)
        patterns.append({(r - minr, c - minc) for r, c in comp})

    out = [row[:] for row in grid]
    for pat in patterns:
        ph = max(r for r, c in pat) + 1
        pw = max(c for r, c in pat) + 1
        for r0 in range(h - ph + 1):
            for c0 in range(w - pw + 1):
                cells = [(r0 + dr, c0 + dc) for dr, dc in pat]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = marker
    return out
